{
  "status": "ok",
  "rules": [
    {
      "field": "cable_cover",
      "property": "visible",
      "condition": {
        "op": "all",
        "args": [
          {"op": "eq", "field": "mains_available", "value": true},
          {"op": "gte", "field": "speaker_units", "value": 2}
        ]
      },
      "quote": "First, display cable cover status exactly when mains power is available and at least 2 speaker units are selected."
    },
    {
      "field": "cable_cover",
      "property": "required",
      "condition": {
        "op": "all",
        "args": [
          {"op": "eq", "field": "venue", "value": "hall"},
          {"op": "not", "arg": {"op": "eq", "field": "steward_present", "value": true}}
        ]
      },
      "quote": "Next, if cable cover status is displayed, demand an answer exactly when the venue is hall or a steward is not present."
    },
    {
      "field": "wind_screen",
      "property": "visible",
      "condition": {
        "op": "eq",
        "field": "venue",
        "value": "open_air"
      },
      "quote": "Then display wind screen status exactly when the venue is open_air."
    },
    {
      "field": "wind_screen",
      "property": "required",
      "condition": {
        "op": "eq",
        "field": "venue",
        "value": "open_air"
      },
      "quote": "Finally, demand an answer to wind screen status whenever it is displayed."
    }
  ]
}
